import org.jboss.ejb3.annotation.TransactionTimeout;
import java.util.concurrent.TimeUnit;

@TransactionTimeout(value = 60, unit = TimeUnit.SECONDS)
public void updateOrder() { /* 業務処理 */ }

import jakarta.transaction.UserTransaction;

ut.setTransactionTimeout(60);
ut.begin();
// この後にXA datasource等を利用する

long appDeadlineNanos = System.nanoTime()
    + TimeUnit.SECONDS.toNanos(60);
// BMT例ではbegin直前に取得し、同じ業務内で保持する

long left = appDeadlineNanos - System.nanoTime();
long usableSeconds = (long) Math.floor(
    left / 1_000_000_000.0) - 20;
if (usableSeconds < 1)
    throw new java.sql.SQLTimeoutException(
        "終了処理の予算不足");

int seconds = (int) Math.min(10L, usableSeconds);
try (java.sql.PreparedStatement ps = con.prepareStatement(
        "UPDATE example_table SET value=? WHERE id=?")) {
    ps.setQueryTimeout(seconds);
    // bindParameters(ps);
    ps.executeUpdate();
}

long remainingNanos = appDeadlineNanos - System.nanoTime();
if (remainingNanos < TimeUnit.SECONDS.toNanos(15))
    throw new java.sql.SQLTimeoutException(
        "commit前の予算不足");
// BMT例：ut.commit();

// CMT: 業務ポリシーに従いrollback-only/例外伝播
// BMT: 状態がACTIVEまたはMARKED_ROLLBACKならrollback
// rollbackの例外は元例外へaddSuppressed等で保持
// SQLTimeoutException / lock timeoutを成功として返さない

